package main

const dashboardHTML = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Corex PC Companion</title><style>
:root{color-scheme:light;--bg:#f4f7f5;--surface:#fff;--text:#17211e;--muted:#65716c;--line:#d7dfda;--accent:#2f766d;--soft:#e7f1ee;--danger:#b42318}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.45 system-ui,-apple-system,"Segoe UI",sans-serif}button,input,textarea,select{font:inherit}.top{position:sticky;top:0;z-index:4;display:flex;align-items:center;justify-content:space-between;padding:14px 22px;border-bottom:1px solid var(--line);background:rgba(255,255,255,.94);backdrop-filter:blur(12px)}.brand{display:flex;align-items:center;gap:12px}.mark{display:grid;place-items:center;width:42px;height:42px;border-radius:13px;background:#174b82;color:#fff;font-weight:900;font-size:21px}.brand b{font-size:20px}.brand small{display:block;color:var(--muted)}.layout{display:grid;grid-template-columns:370px minmax(0,1fr);gap:18px;max-width:1280px;margin:auto;padding:20px}.card{border:1px solid var(--line);border-radius:20px;background:var(--surface);padding:18px;box-shadow:0 12px 34px rgba(20,42,34,.06)}h2{margin:0 0 5px;font-size:19px}p{margin:4px 0 14px;color:var(--muted)}.pin{font-size:36px;font-weight:900;letter-spacing:.16em;color:var(--accent);text-align:center;margin:4px 0}.qr{display:block;width:230px;height:230px;margin:10px auto;border:1px solid var(--line);border-radius:16px}.address{display:grid;gap:7px}.address button,.btn{min-height:44px;padding:8px 13px;border:1px solid var(--line);border-radius:12px;background:#fff;color:var(--text);font-weight:750;cursor:pointer}.address button.on,.btn.primary{border-color:var(--accent);background:var(--accent);color:white}.btn.danger{color:var(--danger)}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.status{margin-top:12px;padding:10px 12px;border-radius:12px;background:var(--soft);color:#255e56;font-weight:700}.device{display:flex;justify-content:space-between;gap:10px;padding:10px 0;border-bottom:1px solid var(--line)}.device:last-child{border:0}.main{min-width:0}.toolbar{display:grid;grid-template-columns:minmax(180px,1fr) auto auto;gap:8px;margin:12px 0}input,textarea{width:100%;border:1px solid var(--line);border-radius:12px;padding:10px 12px;background:#fff;color:var(--text)}.records{display:grid;grid-template-columns:280px minmax(0,1fr);gap:14px;min-height:520px}.keys{border:1px solid var(--line);border-radius:14px;overflow:auto;max-height:620px}.key{display:block;width:100%;padding:10px 12px;border:0;border-bottom:1px solid var(--line);background:#fff;text-align:left;cursor:pointer;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.key.on{background:var(--soft);color:#1f6258;font-weight:800}.editor{display:flex;flex-direction:column;gap:8px}.editor textarea{min-height:480px;resize:vertical;font:13px/1.45 ui-monospace,SFMono-Regular,Consolas,monospace}.empty{padding:32px;text-align:center;color:var(--muted)}.switch{display:flex;align-items:center;gap:9px;margin-top:14px}.switch input{width:18px;height:18px}.fine{font-size:12px;color:var(--muted)}@media(max-width:900px){.layout{grid-template-columns:1fr}.records{grid-template-columns:1fr}.keys{max-height:240px}.editor textarea{min-height:320px}}@media(prefers-color-scheme:dark){:root{color-scheme:dark;--bg:#151b19;--surface:#202724;--text:#eef4f1;--muted:#aeb9b4;--line:#3b4641;--soft:#263d38}.top{background:rgba(28,35,32,.94)}input,textarea,.btn,.address button,.key{background:#202724;color:var(--text)}}
</style></head><body><header class="top"><div class="brand"><div class="mark">C</div><div><b>Corex PC Companion</b><small id="version">Secure local connection</small></div></div><button class="btn danger" id="stop">Stop Companion</button></header>
<div class="layout"><aside><section class="card"><h2>Pair your phone</h2><p>Connect the phone and PC to the same Wi-Fi, phone hotspot, or USB tethering network.</p><div class="pin" id="pin">••••••</div><img class="qr" id="qr" alt="Corex pairing QR code"><div class="address" id="addresses"></div><div class="actions"><button class="btn" id="rotate">New PIN</button></div><div class="status" id="pairStatus">Open this QR with your phone camera, or type the selected address and PIN in Corex.</div></section><section class="card" style="margin-top:18px"><h2>Connected phones</h2><div id="devices" class="fine">No phone paired yet.</div><label class="switch"><input type="checkbox" id="autostart"> Start Corex Companion with Windows</label><p class="fine">Data remains on this PC and paired phones. Protected Windows storage encrypts the saved connection and Corex snapshot.</p></section></aside>
<main class="card main"><h2>Corex records</h2><p>Edit or remove a stored Corex value. Every PC change creates a recoverable safety version before it is sent to the phone.</p><div class="toolbar"><input id="search" placeholder="Search stored data"><button class="btn" id="refresh">Refresh</button><a class="btn" href="/dashboard/export" style="text-decoration:none;text-align:center">Export snapshot</a></div><div class="records"><div class="keys" id="keys"><div class="empty">Waiting for the first phone sync.</div></div><div class="editor"><input id="selected" readonly placeholder="Select a stored item"><textarea id="value" spellcheck="false" placeholder="Select a record to inspect or edit"></textarea><div class="actions"><button class="btn primary" id="save">Save change</button><button class="btn danger" id="remove">Delete</button></div><div class="status" id="dataStatus">Revision 0 · No synchronized phone data yet.</div></div></div></main></div>
<script>
const $=id=>document.getElementById(id);let state=null,data={},selected='',selectedHost='';const fmt=t=>t?new Date(t).toLocaleString():'Never';
async function api(path,options){const response=await fetch(path,options);const value=await response.json().catch(()=>({}));if(!response.ok)throw new Error(value.error||'Corex Companion request failed.');return value}
function renderAddresses(){const root=$('addresses');root.innerHTML='';const addresses=state.addresses||[];if(!selectedHost||!addresses.includes(selectedHost))selectedHost=addresses[0]||'';for(const address of addresses){const button=document.createElement('button');button.textContent=address+':'+state.port;button.classList.toggle('on',address===selectedHost);button.onclick=()=>{selectedHost=address;renderAddresses();renderQR()};root.appendChild(button)}if(!addresses.length)root.innerHTML='<div class="status">No Wi-Fi, hotspot or USB network detected. Connect one and press Refresh.</div>'}
function renderQR(){if(selectedHost)$('qr').src='/dashboard/qr.svg?host='+encodeURIComponent(selectedHost)+'&t='+Date.now();else $('qr').removeAttribute('src')}
function renderDevices(){const root=$('devices'),peers=state.peers||[];if(!peers.length){root.textContent='No phone paired yet.';return}root.innerHTML=peers.map(p=>'<div class="device"><b>'+escapeHtml(p.name||'Corex phone')+'</b><small>'+escapeHtml(fmt(p.lastSeen))+'</small></div>').join('')}
function filteredKeys(){const q=$('search').value.trim().toLowerCase();return Object.keys(data).sort().filter(key=>!q||key.toLowerCase().includes(q)||String(data[key]).toLowerCase().includes(q))}
function renderKeys(){const root=$('keys'),keys=filteredKeys();if(!keys.length){root.innerHTML='<div class="empty">No matching stored values.</div>';return}root.innerHTML='';for(const key of keys){const button=document.createElement('button');button.className='key'+(key===selected?' on':'');button.textContent=key;button.title=key;button.onclick=()=>selectKey(key);root.appendChild(button)}}
function selectKey(key){selected=key;$('selected').value=key;$('value').value=String(data[key]??'');renderKeys()}
function escapeHtml(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function load(){state=await api('/dashboard/state');$('version').textContent='Version '+state.version+' · Secure local connection';$('pin').textContent=state.pin;$('autostart').checked=!!state.autostart;try{data=JSON.parse(state.snapshot||'{}')}catch{data={}};$('dataStatus').textContent='Revision '+state.revision+' · Last dashboard refresh '+new Date().toLocaleTimeString();renderAddresses();renderQR();renderDevices();renderKeys();if(selected&&Object.hasOwn(data,selected))selectKey(selected);else{selected='';$('selected').value='';$('value').value=''}}
async function saveSnapshot(message){const result=await api('/dashboard/update',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({snapshot:JSON.stringify(data)})});state.revision=result.revision;$('dataStatus').textContent=message+' · Revision '+result.revision+' · waiting for phone sync';renderKeys()}
$('save').onclick=async()=>{if(!selected)return;data[selected]=$('value').value;try{await saveSnapshot('Saved '+selected)}catch(e){alert(e.message)}};
$('remove').onclick=async()=>{if(!selected||!confirm('Delete this Corex value? A safety version will be kept on this PC.'))return;const old=selected;delete data[selected];selected='';$('selected').value='';$('value').value='';try{await saveSnapshot('Deleted '+old)}catch(e){alert(e.message)}};
$('rotate').onclick=async()=>{await api('/dashboard/rotate-pin',{method:'POST'});await load()};$('refresh').onclick=load;$('search').oninput=renderKeys;
$('autostart').onchange=async e=>{try{await api('/dashboard/autostart',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:e.target.checked})})}catch(error){e.target.checked=!e.target.checked;alert(error.message)}};
$('stop').onclick=async()=>{if(!confirm('Stop Corex PC Companion? Phone synchronization will pause.'))return;await api('/dashboard/exit',{method:'POST'});document.body.innerHTML='<div class="empty"><h2>Corex PC Companion stopped</h2><p>You can close this browser tab.</p></div>'};
load().catch(e=>$('pairStatus').textContent=e.message);setInterval(()=>{if(document.activeElement!==$('value'))load().catch(()=>{})},15000);
</script></body></html>`
